  "metrics": ["catalog_parts", "set_attr"],
  "where": [
    "{{ Dimension('set__release_year') }} = 2012",
    "({{ Dimension('set__theme_level_1') }} = 'Racers' OR {{ Dimension('set__theme_level_2') }} = 'Racers' OR {{ Dimension('set__theme_level_3') }} = 'Racers')"
  ]
}
```
